draw_config.svg_extra_style:
svg.keymap { background-color: #f4f6fa; font-family: DejaVu Sans, sans-serif; font-size: 14px; fill: #18253c; }
rect.key { fill: #ffffff; stroke: #c6d0df; stroke-width: 1; }
text.label { font-size: 19px; font-weight: 700; fill: #18253c; }
text.hold { fill: #23699a; font-size: 10px; }
text.shifted { fill: #927031; font-size: 10px; }
text.footer { fill: #596b83; font-size: 12px; }
rect.combo { fill: #123756; stroke: #123756; }
text.combo { fill: #ffffff; font-size: 13px; }
text.combo.hold, text.combo.shifted { fill: #dceaf6; font-size: 8px; }
rect.held { fill: #bce5db; stroke: #429a87; }
rect.ghost { fill: #e8edf4; stroke: #d0d9e5; }
text.ghost { fill: #77869a; }
path.combo { stroke: #759cb7; stroke-width: 1.5; fill: none; }

text.label, text.footer { stroke: none; }
